import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Toujours corriger ha-card (expérimental)","description":"Découvrez comment activer en permanence la correction de ha-card avec ce réglage expérimental.","frontmatter":{"title":"Toujours corriger ha-card (expérimental)","description":"Découvrez comment activer en permanence la correction de ha-card avec ce réglage expérimental."},"headers":[],"relativePath":"fr/projects/uix/extras/always-patch-ha-card.md","filePath":"fr/projects/uix/extras/always-patch-ha-card.md","lastUpdated":1792849697000}'),i={name:"fr/projects/uix/extras/always-patch-ha-card.md"};function n(s,e,c,l,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="toujours-corriger-ha-card" tabindex="-1">Toujours corriger ha-card <a class="header-anchor" href="#toujours-corriger-ha-card" aria-label="Permalink to &quot;Toujours corriger ha-card&quot;">​</a></h1><p>Par défaut, UIX ne corrige pas <code>ha-card</code> s&#39;il ne trouve pas de configuration de carte dans le premier élément Frontend ou personnalisé de son arbre DOM parent. Cette option expérimentale permet de toujours corriger l&#39;élément ha-card afin que la variable de thème <code>uix-card(-yaml)</code> puisse s&#39;appliquer. Un <code>ha-card</code> sans configuration peut être utilisé dans des panneaux de configuration ou personnalisés.</p><p>Lorsqu&#39;un <code>ha-card</code> est corrigé sans configuration, la classe <code>type-generic-card</code> lui est ajoutée.</p><h2 id="reglage-depuis-l-interface-de-l-integration" tabindex="-1">Réglage depuis l&#39;interface de l&#39;intégration <a class="header-anchor" href="#reglage-depuis-l-interface-de-l-integration" aria-label="Permalink to &quot;Réglage depuis l&#39;interface de l&#39;intégration&quot;">​</a></h2><p>Cette option est <strong>désactivée par défaut</strong>. Pour l&#39;activer :</p><ol><li>Dans Home Assistant, ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>.</li><li>Sélectionnez <strong>Réglages expérimentaux</strong> dans le menu.</li><li>Activez <strong>Toujours corriger ha-card</strong>.</li><li>Enregistrez.</li></ol><p>Le réglage est disponible immédiatement dans toutes les sessions de navigateur connectées. Un rechargement de la page peut être nécessaire pour qu&#39;il prenne effet.</p><h2 id="comportement-lorsqu-elle-est-activee" tabindex="-1">Comportement lorsqu&#39;elle est activée <a class="header-anchor" href="#comportement-lorsqu-elle-est-activee" aria-label="Permalink to &quot;Comportement lorsqu&#39;elle est activée&quot;">​</a></h2><p>Lorsque cette option est activée :</p><ul><li><code>ha-card</code> est toujours corrigé, même sans configuration de carte disponible.</li><li>Dans ce cas, la classe <code>type-generic-card</code> est ajoutée à <code>ha-card</code>.</li></ul>',10)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
